import csv, math, re, statistics
from collections import defaultdict
PATH='/app/dataset/data.csv'
ITEMS_RE = re.compile(r'items\s*=\s*(\d+)', re.I)
ADJ_RE = re.compile(r'adj\s*=\s*([+-]?\d+(?:\.\d+)?)\s*%', re.I)
FEE_RE = re.compile(r'fee\s*=\s*([+-]?\d+(?:\.\d+)?)', re.I)
WAIVE_RE = re.compile(r'waive\s*=\s*true', re.I)

def parse_amount(s):
    s=(s or '').strip()
    if not s:
        return math.nan
    negative=('CR' in s.upper()) or (s.startswith('(') and s.endswith(')')) or ('-' in s)
    s2=re.sub(r'(?i)C1|C2','',s)
    clean=re.sub(r'[^0-9,.]','',s2)
    if not clean or not re.search(r'\d', clean):
        return math.nan
    lc=clean.rfind(',')
    ld=clean.rfind('.')
    if lc!=-1 and ld!=-1:
        if lc>ld:
            dec=','; thou='.'
        else:
            dec='.'; thou=','
        num=clean.replace(thou,'')
        if dec==',':
            num=num.replace(',','.')
    elif lc!=-1 or ld!=-1:
        sep=',' if lc!=-1 else '.'
        last=clean.rfind(sep)
        digits_after=len(clean)-last-1
        if digits_after==2:
            left=clean[:last].replace(sep,'')
            right=clean[last+1:]
            num=left + '.' + right
        else:
            num=clean.replace(sep,'')
    else:
        num=clean
    return -float(num) if negative else float(num)

def solve(waive_overrides_nan=False, real_net='not_nan'):
    rows=[]
    with open(PATH, newline='') as f:
        r=csv.DictReader(f)
        for i,row in enumerate(r):
            base=parse_amount(row['amount_str'])
            notes=row['notes'] or ''
            m=ITEMS_RE.search(notes); items=int(m.group(1)) if m else None
            m=ADJ_RE.search(notes); adj=float(m.group(1))/100 if m else 0.0
            m=FEE_RE.search(notes); fee=float(m.group(1)) if m else 0.0
            waive=bool(WAIVE_RE.search(notes))
            if waive_overrides_nan:
                if math.isnan(base):
                    net=math.nan
                else:
                    net=base*(1+adj)+fee
                if waive:
                    net=0.0
            else:
                if math.isnan(base):
                    net=math.nan
                else:
                    net=base*(1+adj)+fee
                    if waive:
                        net=0.0
            rows.append({
                'order':i,'record_id':row['record_id'],'event_time':row['event_time'],'region':row['region'],'channel':row['channel'],'net':net,'items':items,
            })
    best={}
    for row in rows:
        cur=best.get(row['record_id'])
        if cur is None:
            best[row['record_id']]=row
            continue
        a,b=row['event_time'],cur['event_time']
        if (a and not b) or (a>b):
            best[row['record_id']]=row
        elif a==b:
            if real_net=='finite':
                a_real=math.isfinite(row['net'])
                b_real=math.isfinite(cur['net'])
            else:
                a_real=not math.isnan(row['net'])
                b_real=not math.isnan(cur['net'])
            if a_real and not b_real:
                best[row['record_id']]=row
    rows=[r for r in best.values() if r['event_time'] and '2025-10-01T00:00:00Z'<=r['event_time']<='2025-12-31T23:59:59Z' and r['channel'].strip().lower()!='phone' and math.isfinite(r['net'])]
    groups=defaultdict(list)
    for r in rows: groups[(r['region'], r['event_time'][:7])].append(r['net'])
    stats={k:(statistics.median(v), statistics.median([abs(x-statistics.median(v)) for x in v])) for k,v in groups.items()}
    for r in rows:
        med,mad=stats[(r['region'], r['event_time'][:7])]
        rz=0.0 if mad==0 else 0.6745*(r['net']-med)/mad
        items_eff=max(r['items'] if r['items'] is not None else 1,1)
        r['robust_z']=rz
        r['anomaly_score']=abs(rz)*math.log1p(items_eff)
    rows.sort(key=lambda r:r['record_id'])
    rows.sort(key=lambda r:r['event_time'], reverse=True)
    rows.sort(key=lambda r:abs(r['robust_z']), reverse=True)
    rows.sort(key=lambda r:r['anomaly_score'], reverse=True)
    return [r['record_id'] for r in rows[:10]]

for waive_overrides_nan in [False, True]:
    for real_net in ['not_nan','finite']:
        print(waive_overrides_nan, real_net, solve(waive_overrides_nan, real_net))
